import{_ as r,o as i,c as l,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const b=JSON.parse('{"title":"CDS Infernalis (Day 1) -- OSD: Less Intrusive Scrub","description":"","frontmatter":{"title":"CDS Infernalis (Day 1) -- OSD: Less Intrusive Scrub","date":"2015-03-06T00:00:00.000Z","updated":"2015-03-06T00:00:00.000Z","tags":["Ceph","scrub","OSD","performance optimization","unified work queue"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2015/CDS_Infernalis_Day_1_--_OSD_-_Less_Intrusive_Scrub.md","filePath":"posts/2015/CDS_Infernalis_Day_1_--_OSD_-_Less_Intrusive_Scrub.md","lastUpdated":1780459816000}'),e={name:"posts/2015/CDS_Infernalis_Day_1_--_OSD_-_Less_Intrusive_Scrub.md"};function n(u,s,_,o,c,a){return i(),l("div",null,[...s[0]||(s[0]=[t("<p>CDS Infernalis (Day 1) 会议的议题集中在Ceph中OSD的scrub功能优化上，旨在减少其对系统性能的影响。以下是会议的主要内容和决定事项：</p><p><strong>会议主题</strong>： 讨论并优化Ceph中OSD的scrub选项，减少其对系统性能的影响。</p><p><strong>关键细节</strong>：</p><ul><li><strong>scrub优化目标</strong>： 减少scrub操作对系统性能的影响，提高效率。</li><li><strong>主要议题</strong>： <ul><li><strong>减少scrub对性能的影响</strong>： 通过随机化scrub调度时间、选择更细粒度的scrub操作、提高scrub操作优先级等措施来减少scrub对系统性能的影响。</li><li><strong>统一工作队列</strong>： 完成统一工作队列的实现，以便更好地管理scrub操作。</li><li><strong>scrub调度策略</strong>： 优化scrub调度策略，使其更加智能，例如根据负载情况进行动态调整。</li><li><strong>优先级问题</strong>： 解决优先级反转问题，确保scrub操作在关键时刻能够获得足够的资源。</li><li><strong>scrub窗口大小</strong>： 调整scrub窗口大小，例如将窗口大小设置为单个对象，以减少调度开销。</li></ul></li></ul><p><strong>决定的事项</strong>：</p><ul><li>完成统一工作队列的实现。</li><li>随机化scrub调度时间，例如将深度scrub间隔设置为一周加减四天。</li><li>选择更细粒度的scrub操作，例如在chunk级别进行决策。</li><li>提高scrub操作优先级，确保其在关键时刻能够获得足够的资源。</li><li>调整scrub窗口大小，例如将窗口大小设置为单个对象。</li><li>实现scrub操作限制，例如限制scrub操作的速度（例如每秒处理的对象数量或每秒处理的字节数）。</li><li>添加健康警告，当无法在指定时间内完成scrub操作时，向管理员发出警告。</li></ul><p><strong>后续行动计划</strong>：</p><ul><li>Sam将负责完成统一工作队列的实现。</li><li>其他研发人员将根据会议讨论结果，进一步优化scrub操作。</li><li>添加健康警告功能。</li><li>评估scrub操作限制的效果。</li></ul><p><strong>关键词</strong>：</p><ul><li>scrub</li><li>OSD</li><li>unified work queue</li><li>priority inversion</li><li>throttling</li><li>quality of service</li></ul>",10)])])}const S=r(e,[["render",n]]);export{b as __pageData,S as default};
